-- Migration: 072_biobank_specimen_ledger_and_ethics_gated_dispense.sql
-- 临床生物样本库 (Biobank) 资产管理、伦理前置合规审查阻断与科研资源借还消耗核销台账
-- 依据标杆文献（清华长庚医院实践）构建深度临床特色生态：生物样本资产、出库伦理硬阻断、领用流转与经费核销

BEGIN;

-- 1. 创建生物样本资产台账表
CREATE TABLE IF NOT EXISTS "生物样本资产" (
    "编号" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "样本编码" character varying(100) NOT NULL UNIQUE,
    "样本类型" character varying(50) NOT NULL,
    "疾病诊断" character varying(200) NOT NULL,
    "解剖部位" character varying(100),
    "储存温度" character varying(50) NOT NULL DEFAULT '-80℃',
    "储存位置" character varying(200) NOT NULL,
    "规格单位" character varying(20) NOT NULL DEFAULT '管',
    "初始数量" numeric(12,2) NOT NULL DEFAULT 1.00,
    "在库余量" numeric(12,2) NOT NULL DEFAULT 1.00,
    "单价成本" numeric(12,2) NOT NULL,
    "质控等级" character varying(20) DEFAULT '一级合格',
    "知情同意书编号" character varying(100),
    "伦理批文号" character varying(100),
    "状态" character varying(30) NOT NULL DEFAULT '在库',
    "采集日期" date DEFAULT CURRENT_DATE,
    "入库日期" date DEFAULT CURRENT_DATE,
    "入库经办人编号" integer NOT NULL,
    "备注" text,
    "建立时间" timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    "更新时间" timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "ck_生物样本资产_余量" CHECK ("在库余量" >= 0 AND "在库余量" <= "初始数量"),
    CONSTRAINT "ck_生物样本资产_状态" CHECK ("状态" IN ('在库', '部分领用', '已借空', '已报损'))
);

CREATE INDEX IF NOT EXISTS "ix_生物样本资产_类型与疾病" 
    ON "生物样本资产" ("样本类型", "疾病诊断", "状态");

CREATE INDEX IF NOT EXISTS "ix_生物样本资产_位置" 
    ON "生物样本资产" ("储存位置");

-- 2. 创建生物样本领用借还与消耗核销台账表
CREATE TABLE IF NOT EXISTS "生物样本领用借还台账" (
    "编号" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "样本编号" integer NOT NULL,
    "项目编号" integer,
    "项目名称" character varying(200),
    "申请人编号" integer NOT NULL,
    "申请人姓名" character varying(50) NOT NULL,
    "申请用途" text NOT NULL,
    "申请数量" numeric(12,2) NOT NULL,
    "出库数量" numeric(12,2) DEFAULT 0.00,
    "归还数量" numeric(12,2) DEFAULT 0.00,
    "消耗数量" numeric(12,2) DEFAULT 0.00,
    "单价成本" numeric(12,2) DEFAULT 0.00,
    "分摊总金额" numeric(14,2) DEFAULT 0.00,
    "伦理批文号" character varying(100),
    "伦理核验结果" character varying(50) NOT NULL DEFAULT '待核验',
    "借还状态" character varying(30) NOT NULL DEFAULT '申请中',
    "申请时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "出库时间" timestamp without time zone,
    "出库经办人" character varying(50),
    "归还时间" timestamp without time zone,
    "归还验收人" character varying(50),
    "核销说明" text,
    "建立时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "更新时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "fk_样本借还_样本" FOREIGN KEY ("样本编号") REFERENCES "生物样本资产"("编号"),
    CONSTRAINT "fk_样本借还_申请人" FOREIGN KEY ("申请人编号") REFERENCES "人员"("编号"),
    CONSTRAINT "ck_样本借还_状态" CHECK ("借还状态" IN ('申请中', '已出库', '已部分归还', '已全部归还', '已消耗核销', '已驳回')),
    CONSTRAINT "ck_样本借还_核验" CHECK ("伦理核验结果" IN ('待核验', '伦理有效已核准', '批文过期硬阻断', '批文缺失硬阻断', '无需伦理'))
);

CREATE INDEX IF NOT EXISTS "ix_样本借还_项目" 
    ON "生物样本领用借还台账" ("项目编号", "借还状态");

CREATE INDEX IF NOT EXISTS "ix_样本借还_申请人" 
    ON "生物样本领用借还台账" ("申请人编号", "借还状态");

-- 3. 存储过程：申请生物样本出库领用 (前置伦理合规硬阻断引擎)
CREATE OR REPLACE FUNCTION sp_生物样本出库领用申请(
    p_样本编号 integer,
    p_项目编号 integer,
    p_申请人编号 integer,
    p_申请用途 text,
    p_申请数量 numeric,
    OUT p_台账编号 integer,
    OUT p_伦理核验结果 character varying(50),
    OUT p_提示消息 text
)
LANGUAGE plpgsql
AS $$
DECLARE
    v_样本 record;
    v_项目 record;
    v_申请人姓名 character varying(50);
    v_项目名称 character varying(200);
    v_伦理结果 character varying(50) := '无需伦理';
    v_批文号 character varying(100) := NULL;
    v_单价 numeric(12,2) := 0.00;
BEGIN
    IF p_申请数量 IS NULL OR p_申请数量 <= 0 THEN
        RAISE EXCEPTION '申请数量必须大于 0';
    END IF;
    -- 1. 检查样本存在性与库存余量
    SELECT * INTO v_样本 FROM "生物样本资产" WHERE "编号" = p_样本编号 FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION '申请失败：指定的生物样本不存在(ID: %)', p_样本编号;
    END IF;

    IF v_样本."在库余量" < p_申请数量 THEN
        RAISE EXCEPTION '申请失败：样本库存余量不足(当前在库: % %, 申请: % %)', 
            v_样本."在库余量", v_样本."规格单位", p_申请数量, v_样本."规格单位";
    END IF;

    v_单价 := v_样本."单价成本";

    -- 2. 获取申请人姓名
    SELECT "姓名" INTO v_申请人姓名 FROM "人员" WHERE "编号" = p_申请人编号 AND "是否启用" = true;
    IF v_申请人姓名 IS NULL THEN
        RAISE EXCEPTION '申请人编号必须对应启用的真实人员：%', p_申请人编号;
    END IF;

    -- 3. 伦理审查前置强校验与硬阻断 (文献标杆：临床人体标本必须具备在期合法伦理批件)
    IF p_项目编号 IS NOT NULL THEN
        SELECT "编号", "项目中文名称", "是否需要伦理批文", "伦理审查状态", "伦理批文有效期至", "伦理批文编号"
          INTO v_项目
          FROM "纵向项目立项"
         WHERE "编号" = p_项目编号;

        IF NOT FOUND THEN
            RAISE EXCEPTION '申请失败：指定的科研项目不存在，不能绕过伦理核验：%', p_项目编号;
        END IF;
        v_项目名称 := v_项目."项目中文名称";

        IF FOUND AND COALESCE(v_项目."是否需要伦理批文", false) = true THEN
            v_批文号 := v_项目."伦理批文编号";
            
            -- 判断是否过期或状态异常
            IF v_项目."伦理审查状态" = '已过期' OR (v_项目."伦理批文有效期至" IS NOT NULL AND v_项目."伦理批文有效期至" < CURRENT_DATE) THEN
                v_伦理结果 := '批文过期硬阻断';
                RAISE EXCEPTION '【临床伦理硬阻断】课题《%》伦理批文[%]已于 % 逾期失效！严禁违规出库领用临床人体生物样本，请先在中枢完成批件续展或修正案！',
                    v_项目."项目中文名称", COALESCE(v_批文号, '未登记'), v_项目."伦理批文有效期至";
            ELSIF v_项目."伦理审查状态" <> '有效' THEN
                v_伦理结果 := '批文缺失硬阻断';
                RAISE EXCEPTION '【临床伦理硬阻断】课题《%》伦理审查状态为[%]，非有效受批状态，禁止领用人体生物样本！',
                    v_项目."项目中文名称", v_项目."伦理审查状态";
            ELSE
                v_伦理结果 := '伦理有效已核准';
            END IF;
        ELSE
            v_伦理结果 := '无需伦理';
        END IF;
    ELSE
        -- 若未指定项目，且样本包含临床组织/血液，提示必须挂靠合规课题
        IF v_样本."样本类型" IN ('冰冻组织', '石蜡切片', '血清', '血浆', '脑脊液') THEN
            RAISE EXCEPTION '【合规阻断】人体临床组织/血液标本出库必须绑定所属立项科研课题以核验伦理批文！';
        END IF;
    END IF;

    -- 4. 写入领用借还台账
    INSERT INTO "生物样本领用借还台账" (
        "样本编号", "项目编号", "项目名称", "申请人编号", "申请人姓名",
        "申请用途", "申请数量", "单价成本", "伦理批文号", "伦理核验结果",
        "借还状态", "申请时间"
    )
    VALUES (
        p_样本编号, p_项目编号, v_项目名称,
        p_申请人编号, v_申请人姓名, p_申请用途, p_申请数量, v_单价,
        v_批文号, v_伦理结果, '申请中', CURRENT_TIMESTAMP
    )
    RETURNING "编号" INTO p_台账编号;

    p_伦理核验结果 := v_伦理结果;
    p_提示消息 := format('样本领用申请成功(单号: %s)，伦理核验通过: %s', p_台账编号, v_伦理结果);
END;
$$;

-- 4. 存储过程：核准出库样本 (扣减库存、更新流转状态、联动资源中心)
CREATE OR REPLACE FUNCTION sp_生物样本核准出库(
    p_台账编号 integer,
    p_出库经办人 character varying(50),
    p_实际出库数量 numeric DEFAULT NULL,
    OUT p_成功 boolean,
    OUT p_提示消息 text
)
LANGUAGE plpgsql
AS $$
DECLARE
    v_台账 record;
    v_样本 record;
    v_出库数 numeric(12,2);
BEGIN
    IF p_出库经办人 IS NULL OR btrim(p_出库经办人) = '' THEN
        RAISE EXCEPTION '出库经办人必须由调用方显式提供';
    END IF;

    SELECT * INTO v_台账 FROM "生物样本领用借还台账" WHERE "编号" = p_台账编号 FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION '出库核准失败：指定的借还台账单不存在(ID: %)', p_台账编号;
    END IF;

    IF v_台账."借还状态" <> '申请中' THEN
        RAISE EXCEPTION '出库核准失败：该单据状态为[%]，非申请中状态', v_台账."借还状态";
    END IF;

    v_出库数 := COALESCE(p_实际出库数量, v_台账."申请数量");
    IF v_出库数 <= 0 OR v_出库数 > v_台账."申请数量" THEN
        RAISE EXCEPTION '实际出库数量必须大于 0 且不超过申请数量';
    END IF;

    SELECT * INTO v_样本 FROM "生物样本资产" WHERE "编号" = v_台账."样本编号" FOR UPDATE;
    IF v_样本."在库余量" < v_出库数 THEN
        RAISE EXCEPTION '出库核准失败：样本当前在库余量(%)不足出库量(%)', v_样本."在库余量", v_出库数;
    END IF;

    -- 扣减在库余量并更新资产状态
    UPDATE "生物样本资产"
       SET "在库余量" = "在库余量" - v_出库数,
           "状态" = CASE WHEN ("在库余量" - v_出库数) = 0 THEN '已借空' ELSE '部分领用' END,
           "更新时间" = CURRENT_TIMESTAMP
     WHERE "编号" = v_台账."样本编号";

    -- 更新借还单据状态
    UPDATE "生物样本领用借还台账"
       SET "出库数量" = v_出库数,
           "出库经办人" = p_出库经办人,
           "出库时间" = CURRENT_TIMESTAMP,
           "借还状态" = '已出库',
           "分摊总金额" = round(v_出库数 * v_台账."单价成本", 2),
           "更新时间" = CURRENT_TIMESTAMP
     WHERE "编号" = p_台账编号;

    -- 联动写入科研资源综合使用记录 (与既有资源池闭环)
    INSERT INTO "科研资源使用记录" (
        "项目编号", "人员编号", "资源类型", "资源名称",
        "申请时间", "实际开始时间", "状态", "数量", "备注", "建立人编号"
    )
    VALUES (
        v_台账."项目编号", v_台账."申请人编号", '生物样本库',
        v_样本."样本编码" || ' (' || v_样本."疾病诊断" || ')',
        v_台账."申请时间", CURRENT_TIMESTAMP, '使用中', v_出库数,
        '领用用途: ' || v_台账."申请用途" || '，经办人: ' || p_出库经办人,
        v_台账."申请人编号"
    );

    p_成功 := true;
    p_提示消息 := format('样本出库核准成功！已出库 %s %s，库存余量更新为 %s', 
        v_出库数, v_样本."规格单位", (v_样本."在库余量" - v_出库数));
END;
$$;

-- 5. 存储过程：归还与消耗核销 (清华长庚医院实践：双向资产核算与经费分摊)
CREATE OR REPLACE FUNCTION sp_生物样本归还与消耗核销(
    p_台账编号 integer,
    p_归还数量 numeric,
    p_消耗数量 numeric,
    p_验收人 character varying(50),
    p_核销说明 text,
    OUT p_成功 boolean,
    OUT p_实际分摊金额 numeric(14,2),
    OUT p_提示消息 text
)
LANGUAGE plpgsql
AS $$
DECLARE
    v_台账 record;
    v_样本 record;
    v_最终状态 character varying(30);
    v_分摊金额 numeric(14,2);
BEGIN
    IF p_验收人 IS NULL OR btrim(p_验收人) = '' THEN
        RAISE EXCEPTION '归还验收人必须由调用方显式提供';
    END IF;
    IF COALESCE(p_归还数量, 0) < 0 OR COALESCE(p_消耗数量, 0) < 0 THEN
        RAISE EXCEPTION '归还数量和消耗数量不能为负数';
    END IF;

    SELECT * INTO v_台账 FROM "生物样本领用借还台账" WHERE "编号" = p_台账编号 FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION '核销失败：指定的单据不存在(ID: %)', p_台账编号;
    END IF;

    IF v_台账."借还状态" <> '已出库' THEN
        RAISE EXCEPTION '核销失败：当前单据状态为[%]，只有已出库单据可办理归还或核销', v_台账."借还状态";
    END IF;

    IF (COALESCE(p_归还数量, 0) + COALESCE(p_消耗数量, 0)) <> v_台账."出库数量" THEN
        RAISE EXCEPTION '核销失败：归还数量(%) + 实验消耗数量(%) 必须严格等于出库数量(%)', 
            p_归还数量, p_消耗数量, v_台账."出库数量";
    END IF;

    SELECT * INTO v_样本 FROM "生物样本资产" WHERE "编号" = v_台账."样本编号" FOR UPDATE;

    -- 回补归还数量至在库余量
    IF COALESCE(p_归还数量, 0) > 0 THEN
        UPDATE "生物样本资产"
           SET "在库余量" = "在库余量" + p_归还数量,
               "状态" = CASE WHEN ("在库余量" + p_归还数量) >= "初始数量" THEN '在库' ELSE '部分领用' END,
               "更新时间" = CURRENT_TIMESTAMP
         WHERE "编号" = v_台账."样本编号";
    END IF;

    -- 计算实际消耗成本金额
    v_分摊金额 := round(COALESCE(p_消耗数量, 0) * v_台账."单价成本", 2);

    IF COALESCE(p_消耗数量, 0) = v_台账."出库数量" THEN
        v_最终状态 := '已消耗核销';
    ELSIF COALESCE(p_归还数量, 0) = v_台账."出库数量" THEN
        v_最终状态 := '已全部归还';
    ELSE
        v_最终状态 := '已部分归还';
    END IF;

    -- 更新借还台账
    UPDATE "生物样本领用借还台账"
       SET "归还数量" = COALESCE(p_归还数量, 0),
           "消耗数量" = COALESCE(p_消耗数量, 0),
           "分摊总金额" = v_分摊金额,
           "归还时间" = CURRENT_TIMESTAMP,
           "归还验收人" = p_验收人,
           "核销说明" = p_核销说明,
           "借还状态" = v_最终状态,
           "更新时间" = CURRENT_TIMESTAMP
     WHERE "编号" = p_台账编号;

    -- 更新科研资源使用记录状态为已完成
    UPDATE "科研资源使用记录"
       SET "实际结束时间" = CURRENT_TIMESTAMP,
           "状态" = '已完成',
           "备注" = "备注" || ' [已完成核销: 归还 ' || COALESCE(p_归还数量, 0) || '，消耗 ' || COALESCE(p_消耗数量, 0) || '，核算金额 ' || v_分摊金额 || '元]'
     WHERE "项目编号" = v_台账."项目编号"
       AND "人员编号" = v_台账."申请人编号"
       AND "资源类型" = '生物样本库'
       AND "状态" = '使用中';

    p_成功 := true;
    p_实际分摊金额 := v_分摊金额;
    p_提示消息 := format('办理成功：归还 %s %s，实验消耗核销 %s %s，分摊科研成本 %s 元。',
        COALESCE(p_归还数量, 0), v_样本."规格单位",
        COALESCE(p_消耗数量, 0), v_样本."规格单位",
        v_分摊金额);
END;
$$;

-- 6. 迁移只创建样本资产结构和合规存储过程。
-- 不写入样本、项目、人员或出库演示记录；真实资产必须由授权人员通过入库流程登记。

-- 8. 记录迁移版本 72
UPDATE "系统迁移版本"
   SET "版本" = 72,
       "脚本" = '072_biobank_specimen_ledger_and_ethics_gated_dispense.sql',
       "检查摘要" = '新增临床生物样本库资产管理、伦理审查硬阻断与出库消耗核销台账',
       "应用时间" = CURRENT_TIMESTAMP
 WHERE "编号" = 1;

COMMIT;
